The program precomputes a symbol lookup table indexed by every possible seed value (0..139967). Each entry is chosen with the same double-precision cumulative comparison as the reference, so the output is identical. Each random draw is then one seed update and one table read. Output goes through a 1 MB buffer to raw stdout, wrapping lines at 60 characters. I have not run it against the reference output.

```csharp
using System;
using System.IO;

class Program
{
    const int M = 139968;
    static byte[] buf = new byte[1 << 20];
    static int pos = 0;
    static Stream outS;

    static void Flush()
    {
        outS.Write(buf, 0, pos);
        pos = 0;
    }

    static byte[] BuildTable(char[] syms, double[] probs)
    {
        byte[] t = new byte[M];
        double[] cum = new double[probs.Length];
        double c = 0;
        for (int i = 0; i < probs.Length; i++) { c += probs[i]; cum[i] = c; }
        for (int s = 0; s < M; s++)
        {
            double r = s / (double)M;
            int k = syms.Length - 1;
            for (int i = 0; i < cum.Length; i++)
            {
                if (cum[i] > r) { k = i; break; }
            }
            t[s] = (byte)syms[k];
        }
        return t;
    }

    static void Header(string h)
    {
        if (pos + h.Length + 2 > buf.Length) Flush();
        for (int i = 0; i < h.Length; i++) buf[pos++] = (byte)h[i];
        buf[pos++] = (byte)'\n';
    }

    static int seed = 42;

    static void RandomSection(byte[] table, long count)
    {
        long rem = count;
        int s = seed;
        while (rem > 0)
        {
            int len = rem < 60 ? (int)rem : 60;
            if (pos + 61 > buf.Length) Flush();
            byte[] b = buf;
            int p = pos;
            for (int i = 0; i < len; i++)
            {
                s = (s * 3877 + 29573) % M;
                b[p++] = table[s];
            }
            b[p++] = (byte)'\n';
            pos = p;
            rem -= len;
        }
        seed = s;
    }

    static void Main(string[] args)
    {
        long n = long.Parse(args[0]);
        outS = Console.OpenStandardOutput();

        string alu =
            "GGCCGGGCGCGGTGGCTCACGCCTGTAATCCCAGCACTTTGGGAGGCCGAGGCGGGCGGA" +
            "TCACCTGAGGTCAGGAGTTCGAGACCAGCCTGGCCAACATGGTGAAACCCCGTCTCTACT" +
            "AAAAATACAAAAATTAGCCGGGCGTGGTGGCGCGCGCCTGTAATCCCAGCTACTCGGGAG" +
            "GCTGAGGCAGGAGAATCGCTTGAACCCGGGAGGCGGAGGTTGCAGTGAGCCGAGATCGCG" +
            "CCACTGCACTCCAGCCTGGGCGACAGAGCGAGACTCCGTCTCAAAAA";
        int al = alu.Length;
        byte[] ab = new byte[al];
        for (int i = 0; i < al; i++) ab[i] = (byte)alu[i];

        Header(">ONE Homo sapiens alu");
        long rem = 2 * n;
        int k = 0;
        while (rem > 0)
        {
            int len = rem < 60 ? (int)rem : 60;
            if (pos + 61 > buf.Length) Flush();
            for (int i = 0; i < len; i++)
            {
                buf[pos++] = ab[k];
                if (++k == al) k = 0;
            }
            buf[pos++] = (byte)'\n';
            rem -= len;
        }

        Header(">TWO IUB ambiguity codes");
        char[] s2 = "acgtBDHKMNRSVWY".ToCharArray();
        double[] p2 = new double[] { 0.27, 0.12, 0.12, 0.27, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02, 0.02 };
        RandomSection(BuildTable(s2, p2), 3 * n);

        Header(">THREE Homo sapiens frequency");
        char[] s3 = "acgt".ToCharArray();
        double[] p3 = new double[] { 0.3029549426680, 0.1979883004921, 0.1975473066391, 0.3015094502008 };
        RandomSection(BuildTable(s3, p3), 5 * n);

        Flush();
        outS.Flush();
    }
}
```

