```csharp
using System;
using System.Numerics;
using System.Text;

public class Program
{
    public static void Main(string[] args)
    {
        int N = int.Parse(args[0]);
        BigInteger q = 1, r = 0, t = 1, n = 3;
        long k = 1, l = 3;
        int count = 0;
        var sb = new StringBuilder();
        var line = new StringBuilder();
        while (count < N)
        {
            if (4 * q + r - t < n * t)
            {
                line.Append((char)('0' + (int)n));
                count++;
                if (count % 10 == 0)
                {
                    sb.Append(line).Append("\t:").Append(count).Append('\n');
                    line.Clear();
                }
                if (count >= N) break;
                BigInteger nr = 10 * (r - n * t);
                n = (10 * (3 * q + r)) / t - 10 * n;
                q *= 10;
                r = nr;
            }
            else
            {
                BigInteger nr = (2 * q + r) * l;
                BigInteger nn = (q * (7 * k + 2) + r * l) / (t * l);
                q *= k;
                t *= l;
                l += 2;
                k += 1;
                n = nn;
                r = nr;
            }
        }
        if (line.Length > 0)
        {
            int len = line.Length;
            line.Append(' ', 10 - len);
            sb.Append(line).Append("\t:").Append(N).Append('\n');
        }
        var o = Console.Out;
        o.Write(sb.ToString());
        o.Flush();
    }
}
