This program reads all of stdin, then handles each FASTA record in turn. It writes the header unchanged, strips newlines from the sequence, and reverse-complements it using a 256-entry lookup table. It re-wraps the output at the width of the record's first sequence line, defaulting to 60.

Lowercase bases map to the uppercase complement, as in the Benchmarks Game version of this task. Any character outside the IUPAC table maps to itself.

```csharp
using System;
using System.IO;

class Program
{
    static void Main(string[] args)
    {
        byte[] data;
        using (var stdin = Console.OpenStandardInput())
        using (var ms = new MemoryStream())
        {
            stdin.CopyTo(ms);
            data = ms.ToArray();
        }

        byte[] map = new byte[256];
        for (int i = 0; i < 256; i++) map[i] = (byte)i;
        string from = "ACGTUMRWSYKVHDBN";
        string to   = "TGCAAKYWSRMBDHVN";
        for (int i = 0; i < from.Length; i++)
        {
            map[from[i]] = (byte)to[i];
            map[char.ToLowerInvariant(from[i])] = (byte)to[i];
        }

        using var stdout = Console.OpenStandardOutput();
        int n = data.Length;
        int pos = 0;
        byte[] seq = new byte[Math.Max(16, n)];
        while (pos < n)
        {
            if (data[pos] == (byte)'>')
            {
                int e = pos;
                while (e < n && data[e] != (byte)'\n') e++;
                int hl = e - pos;
                if (hl > 0 && data[pos + hl - 1] == (byte)'\r') hl--;
                stdout.Write(data, pos, hl);
                stdout.WriteByte((byte)'\n');
                pos = e < n ? e + 1 : n;
            }
            int len = 0;
            int width = 0;
            bool first = true;
            while (pos < n && data[pos] != (byte)'>')
            {
                int lineLen = 0;
                while (pos < n && data[pos] != (byte)'\n')
                {
                    byte b = data[pos++];
                    if (b != (byte)'\r')
                    {
                        seq[len++] = b;
                        lineLen++;
                    }
                }
                if (pos < n) pos++;
                if (first) { width = lineLen; first = false; }
            }
            if (len == 0) continue;
            if (width <= 0) width = 60;
            long outLen = (long)len + len / width + 2;
            byte[] outb = new byte[outLen];
            int o = 0;
            int col = 0;
            for (int i = len - 1; i >= 0; i--)
            {
                outb[o++] = map[seq[i]];
                if (++col == width)
                {
                    outb[o++] = (byte)'\n';
                    col = 0;
                }
            }
            if (col != 0) outb[o++] = (byte)'\n';
            stdout.Write(outb, 0, o);
        }
        stdout.Flush();
    }
}
